 static final class Chain implements XposedInterface.Chain {final Method m;final Object t;final Object[]a;Chain(Method x,Object y,Object[]z){m=x;t=y;a=z;}public Executable getExecutable(){return m;}public Object getThisObject(){return t;}public List<Object>getArgs(){return Arrays.asList(a);}public Object getArg(int i){return a[i];}public Object proceed()throws Throwable{return proceedWith(t,a);}public Object proceed(Object[]x)throws Throwable{return proceedWith(t,x);}public Object proceedWith(Object x)throws Throwable{return proceedWith(x,a);}public Object proceedWith(Object x,Object[]y)throws Throwable{try{return m.invoke(x,y);}catch(InvocationTargetException e){throw e.getCause();}}}
