 static void setup(){XposedInterface api=(XposedInterface)proxy(XposedInterface.class,(p,m,a)->{if(m.getName().equals("hook")){Method target=(Method)a[0];return proxy(XposedInterface.HookBuilder.class,(b,bm,ba)->{if(bm.getName().equals("intercept")){check(!hooks.containsKey(target));hooks.put(target,(XposedInterface.Hooker)ba[0]);if(onInstall!=null)onInstall.run();return proxy(XposedInterface.HookHandle.class,(h,hm,ha)->{if(hm.getName().equals("unhook")){if(failUnhook)throw new IllegalStateException("unhook failed");hooks.remove(target);}if(hm.getName().equals("getExecutable"))return target;return null;});}return b;});}if(m.getReturnType()==int.class)return 102;if(m.getReturnType()==long.class)return 0L;if(m.getReturnType()==boolean.class)return false;if(m.getReturnType()==String.class)return "host-api102";return null;});EzXposed.setBase$hook_xposed_102(api);EzXposed.setHotReloadEnabled(false);}
